using System;using System.IO;using System.Diagnostics;using System.Windows;using System.Windows.Threading;
public static class StartupTests {
 public static void Start(Application app,string folder){Directory.CreateDirectory(folder);Storage.PathName=Path.Combine(folder,"startup-settings.xml");ArchiveStore.DefaultRoot=Path.Combine(folder,"History");var seed=new Settings{SelectedName="本机",SelectedView="文件"};seed.Servers.Add(Storage.LocalServer());Storage.Save(seed);var config=Storage.Load();File.WriteAllText(Path.Combine(folder,"startup-context.txt"),"CONTEXT="+System.Threading.SynchronizationContext.Current.GetType().FullName+"\nSAVED_VIEW="+config.SelectedView);app.DispatcherUnhandledException+=(s,e)=>{File.WriteAllText(Path.Combine(folder,"startup-error.txt"),e.Exception.ToString());e.Handled=true;app.Shutdown(1);};AppDomain.CurrentDomain.UnhandledException+=(s,e)=>File.WriteAllText(Path.Combine(folder,"startup-fatal.txt"),e.ExceptionObject.ToString());var window=new MonitorWindow();app.MainWindow=window;window.Show();var clock=Stopwatch.StartNew();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(300)};timer.Tick+=(s,e)=>{if(clock.Elapsed.TotalSeconds<6)return;bool files=config.SelectedView!="文件"||(window.FileView!=null&&!window.FileView.IsLoading&&window.FileView.VisibleEntryCount>0);if(!files&&clock.Elapsed.TotalSeconds<40)return;timer.Stop();bool okay=window.IsVisible&&window.IsLoaded&&files;File.WriteAllText(Path.Combine(folder,"startup-results.txt"),"WINDOW_VISIBLE="+window.IsVisible+"\nWINDOW_LOADED="+window.IsLoaded+"\nSAVED_PAGE_RESTORED="+files+"\nFILE_ENTRIES="+(window.FileView==null?0:window.FileView.VisibleEntryCount)+"\nELAPSED_SECONDS="+clock.Elapsed.TotalSeconds.ToString("0.0"));window.RenderImage(Path.Combine(folder,"startup-files.png"),1200,900,120);window.Exit();app.Shutdown(okay?0:1);};timer.Start();}
}
